def __unlock__():
    try:
        # لایه ۷: حذف خط‌شکنی + base64 decode
        d = base64.b64decode("".join(__data__.split()))
        
        # لایه ۶: بازسازی ترتیب قطعات
        s = d.decode("utf-8")
        chunk_size = 500
        chunks = [s[i:i+chunk_size] for i in range(0, len(s), chunk_size)]
        
        # ساخت ترتیب اصلی از __order__
        indices = [ord(c) - ord('A') for c in __order__]
        original_chunks = [None] * len(indices)
        for pos, idx in enumerate(indices):
            original_chunks[idx] = chunks[pos]
        scrambled = "".join(original_chunks)
        
        # لایه ۵: بازگردانی hex جابه‌جا شده
        hex_map = {
            'q': '0', 'w': '1', 'e': '2', 'r': '3', 't': '4',
            'y': '5', 'u': '6', 'i': '7', 'o': '8', 'p': '9',
            'a': 'a', 's': 'b', 'd': 'c', 'f': 'd', 'g': 'e', 'h': 'f'
        }
        hexed = "".join(hex_map[c] for c in scrambled)
        
        # لایه ۴: hex به bytes
        b85 = bytes.fromhex(hexed)
        
        # لایه ۳: base85 decode
        b64 = base64.b85decode(b85)
        
        # لایه ۲: base64 decode
        compressed = base64.b64decode(b64)
        
        # لایه ۱: zlib decompress
        xor_bytes = zlib.decompress(compressed)
        
        # لایه ۰: XOR با کلید
        kb = __key__.encode("utf-8")
        code_bytes = bytes(b ^ kb[i % len(kb)] for i, b in enumerate(xor_bytes))
        return code_bytes.decode("utf-8")
    except Exception as e:
        raise RuntimeError("Locked file corrupted or wrong key!") from e

exec(compile(__unlock__(), "<Mahyar>", "exec"))

